-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the dca capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- dca / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'dca' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book dca refused: dca/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd0ce045183ad563215b9dc1c423b6531' and fields = '[{"key": "qi_bpd", "tol": 0.5, "unit": "stb/d", "label": "Fitted initial rate qi", "expected": 120}, {"key": "di_per_day", "tol": 0.00002, "unit": "1/d", "label": "Fitted nominal decline Di", "expected": 0.0012}, {"key": "eur_10_stb", "tol": 500, "unit": "stb", "label": "EUR at the 10 stb/d limit", "expected": 91666.6666666667}, {"key": "t_limit_days", "tol": 10, "unit": "days", "label": "Time to the 10 stb/d limit", "expected": 2070.75554149}, {"key": "np_flood_stb", "tol": 400, "unit": "stb", "label": "Cumulative production at 2023-01-01", "expected": 73157.9366256283}, {"key": "eff_decline_pct", "tol": 0.1, "unit": "%/yr", "label": "Tangent effective annual decline", "expected": 35.4674217142705}]'::jsonb then 'old'
              when md5(prompt) = '7d87fccbd3f558980c6ce341fe276454' and fields = '[{"key": "qi_bpd", "tol": 0.5, "unit": "stb/d", "label": "Fitted initial rate qi", "expected": 120}, {"key": "di_per_day", "tol": 0.00002, "unit": "1/d", "label": "Fitted nominal decline Di", "expected": 0.0012}, {"key": "eur_10_stb", "tol": 500, "unit": "stb", "label": "EUR at the 10 stb/d limit", "expected": 91666.6666666667}, {"key": "t_limit_days", "tol": 10, "unit": "days", "label": "Time to the 10 stb/d limit", "expected": 2070.75554149}, {"key": "np_flood_stb", "tol": 400, "unit": "stb", "label": "Cumulative production at 2023-01-01", "expected": 73157.9366256283}, {"key": "eff_decline_pct", "tol": 0.1, "unit": "%/yr", "label": "Tangent effective annual decline", "expected": 35.4674217142705}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'dca' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book dca refused: dca/beginner matches neither its published form (prompt md5 d0ce045183ad563215b9dc1c423b6531) nor its W1 form (prompt md5 7d87fccbd3f558980c6ce341fe276454), with the fields this file was generated against';
  end if;

  -- dca / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'dca' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book dca refused: dca/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '811e55d836a27e610ec33e0822585d81' and fields = '[{"key": "e3_b", "tol": 0.02, "unit": "-", "label": "Ekene-3 fitted decline exponent b", "expected": 0.5}, {"key": "e3_eur_stb", "tol": 600, "unit": "stb", "label": "Ekene-3 EUR at 10 stb/d", "expected": 111270.166537926}, {"key": "e6_win_di", "tol": 0.00002, "unit": "1/d", "label": "Ekene-6 windowed-to-primary Di", "expected": 0.001}, {"key": "e1_naive_r2", "tol": 0.01, "unit": "-", "label": "Ekene-1 full-history fit R2", "expected": 0.818388421218434}, {"key": "tc_eur_stb", "tol": 50, "unit": "stb", "label": "Ekene-6 EUR from the fixed-b type curve", "expected": 91524.2759502962}, {"key": "field_eur_stb", "tol": 2000, "unit": "stb", "label": "Sum of the four closed-form EURs at 10 stb/d", "expected": 461709.132532792}]'::jsonb then 'old'
              when md5(prompt) = 'ee0b5228d4cbd5ed1dabc4e28c97712b' and fields = '[{"key": "e3_b", "tol": 0.02, "unit": "-", "label": "Ekene-3 fitted decline exponent b", "expected": 0.5}, {"key": "e3_eur_stb", "tol": 600, "unit": "stb", "label": "Ekene-3 EUR at 10 stb/d", "expected": 111270.166537926}, {"key": "e6_win_di", "tol": 0.00002, "unit": "1/d", "label": "Ekene-6 windowed-to-primary Di", "expected": 0.001}, {"key": "e1_naive_r2", "tol": 0.01, "unit": "-", "label": "Ekene-1 full-history fit R2", "expected": 0.818388421218434}, {"key": "tc_eur_stb", "tol": 50, "unit": "stb", "label": "Ekene-6 EUR from the fixed-b type curve", "expected": 91524.2759502962}, {"key": "field_eur_stb", "tol": 2000, "unit": "stb", "label": "Sum of the four closed-form EURs at 10 stb/d", "expected": 461709.132532792}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'dca' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book dca refused: dca/intermediate matches neither its published form (prompt md5 811e55d836a27e610ec33e0822585d81) nor its W1 form (prompt md5 ee0b5228d4cbd5ed1dabc4e28c97712b), with the fields this file was generated against';
  end if;

  -- dca / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'dca' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book dca refused: dca/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e12d7d68850db343163050fbf06acc91' and fields = '[{"key": "e5_late_di", "tol": 0.000005, "unit": "1/d", "label": "Ekene-5 post-ramp fitted Di (2024-05-01 on)", "expected": 0.00035}, {"key": "e6_oil_di", "tol": 0.000002, "unit": "1/d", "label": "Ekene-6 oil decline on the same window", "expected": 0.0013275893489185155}, {"key": "b12_eur_stb", "tol": 2000, "unit": "stb", "label": "EUR at b 1.2 (Ekene-1 primary fit, limit 10)", "expected": 321875.914758613}, {"key": "b_ratio", "tol": 0.02, "unit": "-", "label": "b 1.2 EUR over the exponential EUR", "expected": 3.5113736155485}, {"key": "p90_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P90 (low)", "expected": 420425.025054486}, {"key": "p10_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P10 (high)", "expected": 531360.331525141}]'::jsonb then 'old'
              when md5(prompt) = '76875a05508b4eddb95a2c9507e4895d' and fields = '[{"key": "e5_late_di", "tol": 0.000005, "unit": "1/d", "label": "Ekene-5 post-ramp fitted Di (2024-05-01 on)", "expected": 0.00035}, {"key": "e6_oil_di", "tol": 0.000002, "unit": "1/d", "label": "Ekene-6 oil decline on the same window", "expected": 0.0013275893489185155}, {"key": "b12_eur_stb", "tol": 2000, "unit": "stb", "label": "EUR at b 1.2 (Ekene-1 primary fit, limit 10)", "expected": 321875.914758613}, {"key": "b_ratio", "tol": 0.02, "unit": "-", "label": "b 1.2 EUR over the exponential EUR", "expected": 3.5113736155485}, {"key": "p90_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P90 (low)", "expected": 420425.025054486}, {"key": "p10_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P10 (high)", "expected": 531360.331525141}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'dca' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book dca refused: dca/advanced matches neither its published form (prompt md5 e12d7d68850db343163050fbf06acc91) nor its W1 form (prompt md5 76875a05508b4eddb95a2c9507e4895d), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book dca: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book dca refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Fit Ekene-1''s primary window (its monthly rates from 2020-01-01 through 2022-12-01, before the flood response) with the real engine, then book the well: the fitted initial rate and nominal decline, the EUR and the time to the 10 stb/d economic limit, the cumulative production at the flood start, and the tangent effective annual decline.',
           fields = '[{"key": "qi_bpd", "tol": 0.5, "unit": "stb/d", "label": "Fitted initial rate qi", "expected": 120}, {"key": "di_per_day", "tol": 0.00002, "unit": "1/d", "label": "Fitted nominal decline Di", "expected": 0.0012}, {"key": "eur_10_stb", "tol": 500, "unit": "stb", "label": "EUR at the 10 stb/d limit", "expected": 91666.6666666667}, {"key": "t_limit_days", "tol": 10, "unit": "days", "label": "Time to the 10 stb/d limit", "expected": 2070.75554149}, {"key": "np_flood_stb", "tol": 400, "unit": "stb", "label": "Cumulative production at 2023-01-01", "expected": 73157.9366256283}, {"key": "eff_decline_pct", "tol": 0.1, "unit": "%/yr", "label": "Tangent effective annual decline", "expected": 35.4674217142705}]'::jsonb
     where app_slug = 'dca' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book dca refused: dca/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '7d87fccbd3f558980c6ce341fe276454' and fields = '[{"key": "qi_bpd", "tol": 0.5, "unit": "stb/d", "label": "Fitted initial rate qi", "expected": 120}, {"key": "di_per_day", "tol": 0.00002, "unit": "1/d", "label": "Fitted nominal decline Di", "expected": 0.0012}, {"key": "eur_10_stb", "tol": 500, "unit": "stb", "label": "EUR at the 10 stb/d limit", "expected": 91666.6666666667}, {"key": "t_limit_days", "tol": 10, "unit": "days", "label": "Time to the 10 stb/d limit", "expected": 2070.75554149}, {"key": "np_flood_stb", "tol": 400, "unit": "stb", "label": "Cumulative production at 2023-01-01", "expected": 73157.9366256283}, {"key": "eff_decline_pct", "tol": 0.1, "unit": "%/yr", "label": "Tangent effective annual decline", "expected": 35.4674217142705}]'::jsonb) from public.academy_capstones where app_slug = 'dca' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book dca refused: dca/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Work the Ekene field like a portfolio: identify Ekene-3''s decline exponent from its primary window and book its EUR at the 10 stb/d limit; window Ekene-6 to the primary and report its fitted Di; read the R2 of the invalid full-history auto-fit of Ekene-1; book Ekene-6 from the pooled Ekene-3 + Ekene-6 type curve applied fixed-b; and total the four wells'' closed-form EURs.',
           fields = '[{"key": "e3_b", "tol": 0.02, "unit": "-", "label": "Ekene-3 fitted decline exponent b", "expected": 0.5}, {"key": "e3_eur_stb", "tol": 600, "unit": "stb", "label": "Ekene-3 EUR at 10 stb/d", "expected": 111270.166537926}, {"key": "e6_win_di", "tol": 0.00002, "unit": "1/d", "label": "Ekene-6 windowed-to-primary Di", "expected": 0.001}, {"key": "e1_naive_r2", "tol": 0.01, "unit": "-", "label": "Ekene-1 full-history fit R2", "expected": 0.818388421218434}, {"key": "tc_eur_stb", "tol": 50, "unit": "stb", "label": "Ekene-6 EUR from the fixed-b type curve", "expected": 91524.2759502962}, {"key": "field_eur_stb", "tol": 2000, "unit": "stb", "label": "Sum of the four closed-form EURs at 10 stb/d", "expected": 461709.132532792}]'::jsonb
     where app_slug = 'dca' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book dca refused: dca/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'ee0b5228d4cbd5ed1dabc4e28c97712b' and fields = '[{"key": "e3_b", "tol": 0.02, "unit": "-", "label": "Ekene-3 fitted decline exponent b", "expected": 0.5}, {"key": "e3_eur_stb", "tol": 600, "unit": "stb", "label": "Ekene-3 EUR at 10 stb/d", "expected": 111270.166537926}, {"key": "e6_win_di", "tol": 0.00002, "unit": "1/d", "label": "Ekene-6 windowed-to-primary Di", "expected": 0.001}, {"key": "e1_naive_r2", "tol": 0.01, "unit": "-", "label": "Ekene-1 full-history fit R2", "expected": 0.818388421218434}, {"key": "tc_eur_stb", "tol": 50, "unit": "stb", "label": "Ekene-6 EUR from the fixed-b type curve", "expected": 91524.2759502962}, {"key": "field_eur_stb", "tol": 2000, "unit": "stb", "label": "Sum of the four closed-form EURs at 10 stb/d", "expected": 461709.132532792}]'::jsonb) from public.academy_capstones where app_slug = 'dca' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book dca refused: dca/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Refit Ekene-5 on the fully post-ramp window (2024-05-01 onward) and report its fitted nominal decline. On that SAME window, refit Ekene-6, whose water cut is climbing, and report its fitted decline: the two wells share a reservoir and a gross decline, so the difference is the water cut alone. Then book the b = 1.2 EUR on Ekene-1''s pre-flood primary window, fitting its qi and Di yourself before you book, at a 10 stb/d limit, with its ratio to the exponential booking of the same data. Finally compute the field triangle''s P90 and P10, petroleum convention with P90 low, from a minimum of 380000 stb, a maximum of 580000 stb, and a mode that is the field''s deterministic booking: the sum of the four producers'' closed-form EURs at the same 10 stb/d limit, which you must total yourself.',
           fields = '[{"key": "e5_late_di", "tol": 0.000005, "unit": "1/d", "label": "Ekene-5 post-ramp fitted Di (2024-05-01 on)", "expected": 0.00035}, {"key": "e6_oil_di", "tol": 0.000002, "unit": "1/d", "label": "Ekene-6 oil decline on the same window", "expected": 0.0013275893489185155}, {"key": "b12_eur_stb", "tol": 2000, "unit": "stb", "label": "EUR at b 1.2 (Ekene-1 primary fit, limit 10)", "expected": 321875.914758613}, {"key": "b_ratio", "tol": 0.02, "unit": "-", "label": "b 1.2 EUR over the exponential EUR", "expected": 3.5113736155485}, {"key": "p90_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P90 (low)", "expected": 420425.025054486}, {"key": "p10_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P10 (high)", "expected": 531360.331525141}]'::jsonb
     where app_slug = 'dca' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book dca refused: dca/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '76875a05508b4eddb95a2c9507e4895d' and fields = '[{"key": "e5_late_di", "tol": 0.000005, "unit": "1/d", "label": "Ekene-5 post-ramp fitted Di (2024-05-01 on)", "expected": 0.00035}, {"key": "e6_oil_di", "tol": 0.000002, "unit": "1/d", "label": "Ekene-6 oil decline on the same window", "expected": 0.0013275893489185155}, {"key": "b12_eur_stb", "tol": 2000, "unit": "stb", "label": "EUR at b 1.2 (Ekene-1 primary fit, limit 10)", "expected": 321875.914758613}, {"key": "b_ratio", "tol": 0.02, "unit": "-", "label": "b 1.2 EUR over the exponential EUR", "expected": 3.5113736155485}, {"key": "p90_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P90 (low)", "expected": 420425.025054486}, {"key": "p10_stb", "tol": 2000, "unit": "stb", "label": "Field triangle P10 (high)", "expected": 531360.331525141}]'::jsonb) from public.academy_capstones where app_slug = 'dca' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book dca refused: dca/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book dca: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
